/**
 * Content translation layer (separate from UI i18n in `i18n.ts`).
 *
 * A lot of user-facing text is CONTENT, not chrome: lesson & unit titles and
 * summaries authored in Spanish in the SQLite seed, plus recommendation copy
 * generated by the Rust backend (guidance.rs / skill insights). None of it goes
 * through `useT()`. This module translates those Spanish content strings to
 * English at render time so the app is fully usable in English — no DB schema
 * change needed, and it works for the shared Mac + Windows frontend.
 *
 *   const tc = useTc();
 *   <h2>{tc(lesson.title)}</h2>
 *
 * Matching is: exact dictionary hit first, then regex RULES for the dynamic
 * backend strings that embed counts (e.g. "Tienes 3 repasos esperando"). If
 * nothing matches, the original Spanish is returned unchanged (safe fallback).
 */

