// Regex rules for dynamic backend strings with embedded counts. Each rule maps
// the Spanish template to an English builder using captured groups.
const RULES: { re: RegExp; en: (m: RegExpMatchArray) => string }[] = [
  {
    re: /^Tienes (\d+) repasos? esperando$/,
    en: (m) => `You have ${m[1]} review${m[1] === "1" ? "" : "s"} waiting`,
  },
  {
    re: /^Aprende (\d+) kanji nuevos?$/,
    en: (m) => `Learn ${m[1]} new kanji`,
  },
  {
    re: /^Tienes (\d+) kanji dominados?\. Sigue construyendo tu base\.$/,
    en: (m) => `You have ${m[1]} kanji mastered. Keep building your base.`,
  },
  {
    re: /^Continúa con "(.+)"$/,
    en: (m) => `Continue with "${translateContent(m[1], "en")}"`,
  },
  {
    re: /^Tu punto a reforzar hoy es (.+) \((\d+)% de aciertos\)\. Le dedicamos un momento y subimos esa cifra\.$/,
    en: (m) =>
      `Today's spot to reinforce is ${translateContent(m[1], "en")} (${m[2]}% accuracy). Let's spend a moment and raise that number.`,
  },
  {
    re: /^Sigue practicando un poco más y personalizaré tu plan según tus aciertos\.$/,
    en: () =>
      "Keep practicing a bit more and I'll personalize your plan based on your accuracy.",
  },
  // ── Generated exercise prompt templates (exercises.rs) ──────────────────
  { re: /^¿Cuál corresponde a «(.+)»\?$/, en: (m) => `Which one is «${translateContent(m[1], "en")}»?` },
  { re: /^Completa la frase — «(.+)»$/, en: (m) => `Complete the sentence — «${translateContent(m[1], "en")}»` },
  { re: /^En esa situación se dice «(.+)»\.$/, en: (m) => `In that situation you say «${m[1]}».` },
  {
    re: /^(.+) significa «(.+)»\.?( Se lee (.+?)\.)?( Ejemplo: (.+?) — (.+))?$/,
    en: (m) => {
      let s = `${m[1]} means «${translateContent(m[2], "en")}»`;
      if (m[4]) s += `. It's read ${m[4]}`;
      if (m[6]) s += `. Example: ${m[6]} — ${translateContent(m[7], "en")}`;
      return s + ".";
    },
  },
];

/** Non-reactive content translate. */
export function translateContent(text: string, lang: NarrationLang): string {
  if (lang !== "en" || !text) return text;
  const trimmed = text.trim();
  if (CONTENT[trimmed]) return CONTENT[trimmed];
  for (const rule of RULES) {
    const m = trimmed.match(rule.re);
    if (m) return rule.en(m);
  }
  return text;
}

/** Reactive alias for use outside a hook context via the store. */
export function tc(text: string): string {
  return translateContent(text, useLanguage.getState().lang);
}

/** React hook returning a content-translate bound to the current language. */
export function useTc(): (text: string) => string {
  const lang = useLanguage((s) => s.lang);
  return (text: string) => translateContent(text, lang);
}
